  function migrateLegacy(){try{const legacy=JSON.parse(localStorage.getItem('xhs-growth-os-state')||'null');const v6=JSON.parse(localStorage.getItem('xhs-growth-os-v6')||'null');const v8=JSON.parse(localStorage.getItem('xhs-growth-os-v8')||'null');if(!legacy&&!v6&&!v8)return null;const next=clone(seed);if(legacy&&legacy.profile){next.account.name=legacy.profile.name||next.account.name;next.account.id=legacy.profile.id||next.account.id;next.account.bio=legacy.profile.bio||next.account.bio}if(legacy&&Array.isArray(legacy.tasks)){next.tasks=legacy.tasks.map(function(t,i){if(t&&!Array.isArray(t)&&typeof t==='object')return Object.assign({},t,{id:t.id||'legacy_task_'+i});return {id:'legacy_task_'+i,title:t[0]||'未命名任务',priority:t[1]==='高'?'high':t[1]==='低'?'low':'medium',status:t[2]==='已完成'?'done':t[2]==='进行中'?'doing':'todo',dueAt:t[3]==='明天'?'2026-10-14':'2026-10-13',source:t[4]==='AI 推荐'?'ai':'manual'}})}if(legacy&&Array.isArray(legacy.notes)){next.contents=legacy.notes.map(function(n,i){return {id:'legacy_content_'+i,title:n[0]||'未命名内容',category:n[1]||'运营经验',publishedAt:'2026-10-13',status:n[3]==='草稿'?'draft':'published',views:parseInt(String(n[4]||'0').replace(/,/g,''),10)||0,likes:0,saves:0,comments:0,rate:parseFloat(String(n[5]||'0').replace('%',''))||0}})}const range=(v6&&v6.dateRange)||(v8&&v8.dateRange);if(range)next.metrics.range=range==='30天'||range==='30d'?'30d':range==='90天'||range==='90d'?'90d':'7d';return next}catch(e){return null}}
