  async function hydrateAnalyticsData(){if(!ui.serverReady)return;try{const data=await apiFetch('/api/analytics?range='+encodeURIComponent(store.metrics.range||'7d'),{method:'GET'});store.analytics=data;if(data.cards)store.metrics.cards=Object.assign(store.metrics.cards,{followers:data.cards.followers||store.metrics.cards.followers,exposure:data.cards.exposure,likes:data.cards.likes,saves:data.cards.saves,comments:data.cards.comments,interaction:data.cards.interaction});store.meta=Object.assign({},store.meta,{source:'server',analyticsUpdatedAt:data.updatedAt});persistLocal()}catch(error){if(error.code!=='AUTH_REQUIRED')toast('分析数据暂不可用',error.message||'继续使用本地数据')}}
  async function hydrateServerData(){try{const sessionData=await apiFetch('/api/auth/session',{method:'GET'});ui.demoSession={email:sessionData.user.email,id:sessionData.user.id,source:'server'};ui.serverReady=true;ui.serverSource='server';const data=await apiFetch('/api/data',{method:'GET'});if(data.user)store.user=Object.assign(store.user,data.user);if(data.account)store.account=Object.assign(store.account,data.account,{status:data.account.status||store.account.status});if(Array.isArray(data.contents))store.contents=data.contents;if(Array.isArray(data.tasks))store.tasks=data.tasks;store.meta=Object.assign({},store.meta,{source:'server',hydratedAt:new Date().toISOString()});await hydrateAnalyticsData();await hydrateCommercialData();await hydrateAIProviders();persistLocal();if(ui.page==='login'||ui.page==='register'){ui.page=ui.authRedirect||'dashboard';ui.authRedirect=''}render()}catch(error){if(error.code!=='AUTH_REQUIRED')toast('服务端数据暂不可用',error.message||'当前继续使用本地演示数据')}}
