  function stateCard(kind,title,description,action,label){const iconMap={first:'✦',loading:'◌',generating:'✦',timeout:'⌁',config:'⚙',model:'!',account:'◎',empty:'○',permission:'⛔',offline:'⌁'};const tone=kind==='model'||kind==='timeout'||kind==='offline'?'error':kind==='config'||kind==='account'||kind==='permission'?'warning':'neutral';return '<div class="growth-state-card '+tone+' '+kind+'"><span class="growth-state-icon">'+(iconMap[kind]||'•')+'</span><div><b>'+esc(title)+'</b><p>'+esc(description)+'</p>'+(action?'<button class="growth-action" data-state-action="'+esc(action)+'">'+esc(label||'处理')+'</button>':'')+'</div></div>'}
  function globalStatus(){let html='';if(ui.networkStatus==='offline')html+=stateCard('offline','网络已断开','当前无法连接服务，已保留本地内容。网络恢复后可以继续重试。','retry-network','重新检查');if(ui.firstVisit&&ui.page==='dashboard')html+=stateCard('first','欢迎使用 AI Growth OS','这是你的第一次使用。先查看演示数据，再连接账号或从 AI 创作开始。','dismiss-first','知道了');if(isProtectedPage(ui.page)&&ui.page!=='settings'){const c=connectionInfo();if(c.status==='unbound')html+='<div class="growth-inline-notice"><span>当前使用演示数据 · 账号尚未绑定</span><button class="growth-action" data-page="settings">去设置账号接入</button></div>';if(c.status==='connected'&&(!Array.isArray(c.permissions)||!c.permissions.length))html+=stateCard('permission','暂无数据权限','账号已验证，但服务端没有返回可用的数据权限。请检查授权范围。','settings','检查设置')}if(ui.page==='analytics'&&!store.contents.some(function(x){return x.status==='published'}))html+=stateCard('empty','暂无数据','还没有已发布内容，趋势和贡献排行将在同步数据后出现。','settings','检查数据源');if(ui.page==='content'&&!store.contents.length)html+=stateCard('empty','暂无内容','先创建一篇草稿，内容管理会记录从灵感到数据回流的完整生命周期。','new-content','新建内容');if(ui.page==='tasks'&&!store.tasks.length)html+=stateCard('empty','暂无任务','把 AI 建议或你的计划转成第一个可执行任务。','new-task','创建任务');return html}
  function stateAction(action){if(action==='dismiss-first'){ui.firstVisit=false;save();render();return}if(action==='retry-network'){ui.networkStatus=typeof navigator!=='undefined'&&navigator.onLine?'online':'offline';if(ui.networkStatus==='online')render();else toast('网络仍未连接','请检查网络后重试');return}if(action==='go-settings'||action==='settings'){navigate('settings');return}if(action==='go-login'){navigate('login');return}if(action==='test-ai'){testAI();return}if(action==='test-account'){testAccountConnection();return}if(action==='new-content'){openCreateForm('content');return}if(action==='new-task'){openCreateForm('task');return}if(action==='connect-account'){openConnectionForm();return}if(action==='retry-ai'){const q=ui.lastAIQuestion||'请继续解读当前数据';ui.aiStatus='idle';render();aiAsk(q);return}if(action==='retry-creation'){ui.creationStatus='idle';render();generateWithAI();return}if(action==='reload'){window.location.reload()}}
  function icon(name){const icons={search:'⌕',bell:'♧',calendar:'▣',robot:'✦',home:'⌂',chart:'▥',content:'▤',task:'☑',idea:'♢',settings:'⚙',plus:'＋',close:'×'};return '<span class="ui-icon">'+(icons[name]||'•')+'</span>'}
  function fmtDate(s){return s==='2026-10-13'?'今天':s==='2026-10-14'?'明天':s.replace(/2026-/,'').replace('-','.')}
  function priorityLabel(p){return p==='high'?'高':p==='medium'?'中':'低'}
  function statusLabel(s){return s==='todo'?'待完成':s==='doing'?'进行中':s==='done'?'已完成':'草稿'}
  function contentStatusLabel(s){return s==='published'?'已发布':s==='scheduled'?'待发布':s==='failed'?'发布失败':'草稿'}
  function contentStatusClass(s){return s==='published'?'done':s==='scheduled'?'doing':s==='failed'?'high':'gray'}
  function contentDataLabel(content){if(content.status==='published'&&Number(content.views||0)>0)return '数据已回流';if(content.status==='published')return '等待数据';if(content.status==='failed')return content.publishError||'发布失败，请检查内容和账号状态';return '尚未发布'}
  function saveContentVersion(content,label){if(!content)return;const versions=Array.isArray(content.versions)?content.versions:[];versions.push({id:uid('content_version'),label:label||'内容版本',at:new Date().toISOString(),title:content.title,body:content.body||'',plan:clone(content.plan||{})});content.versions=versions.slice(-8)}
  function rankValue(content,key){return key==='likes'?content.likes:key==='saves'?content.saves:key==='comments'?content.comments:key==='rate'?content.rate:content.views}
  function rankLabel(key){return {views:'曝光量',likes:'点赞',saves:'收藏',comments:'评论',rate:'互动率'}[key]||'曝光量'}
  function taskDueState(task){if(task.status==='done')return 'done';const due=String(task.dueAt||'');if(!due)return 'none';if(due<today)return 'overdue';if(due===today)return 'today';return 'upcoming'}
  function taskDueText(task){const state=taskDueState(task);return state==='overdue'?'已逾期':state==='today'?'今天到期':state==='upcoming'?'截止 '+fmtDate(task.dueAt):''}
  function taskDueClass(task){return taskDueState(task)==='overdue'||taskDueState(task)==='today'?'high':'doing'}
  function taskProgress(task){const steps=Array.isArray(task.subtasks)?task.subtasks:[];if(!steps.length)return '';return steps.filter(function(s){return typeof s==='object'&&s.status==='done'}).length+'/'+steps.length}
function compareContentVersion(contentId,versionId){const content=store.contents.find(function(x){return x.id===contentId});const version=content&&(content.versions||[]).find(function(x){return x.id===versionId});if(!version)return;const body='<div class="growth-form-row"><div class="growth-output-block"><b>当前内容</b><p>标题：'+esc(content.title)+'</p><p>正文：'+esc(String(content.body||'').slice(0,180))+'…</p></div><div class="growth-output-block"><b>'+esc(version.label)+'</b><p>标题：'+esc(version.title)+'</p><p>正文：'+esc(String(version.body||'').slice(0,180))+'…</p></div></div>';modal('内容版本对比','对比当前内容与历史版本。',body,'关闭',function(){return true})}
  function restoreContentVersion(contentId,versionId){const content=store.contents.find(function(x){return x.id===contentId});const version=content&&(content.versions||[]).find(function(x){return x.id===versionId});if(!content||!version)return;content.title=version.title;content.body=version.body;content.plan=clone(version.plan||{});save();render();toast('已恢复内容版本',version.label)}

  function metricDefinition(key){return {exposure:'曝光量：内容被展示给用户的次数，反映分发覆盖。',interaction:'互动量：点赞、收藏、评论等有效行为总和。',followers:'粉丝数：当前账号关注者数量，反映长期沉淀。'}[key]||'该指标用于观察账号在当前周期内的增长表现。'}
  function metricComparison(key){const live=store.analytics&&store.analytics.comparison;const liveMap={exposure:live&&live.exposure,interaction:live&&live.interaction,followers:live&&live.followers};if(liveMap[key]!==undefined)return {mom:(liveMap[key]>=0?'+':'')+liveMap[key]+'%',yoy:'服务端周期对比'};return {exposure:{mom:'+18.4%',yoy:'+26.8%'},interaction:{mom:'+2.1%',yoy:'+8.6%'},followers:{mom:'+6.8%',yoy:'+14.2%'}}[key]||{mom:'+12.3%',yoy:'+18.1%'}}
  function metricCompareLabel(){return '环比上一个 '+rangeLabel().replace('近 ','')+' · 同比去年同期'}
  function analyticsDateMatch(content){if(ui.analyticsDate==='all')return true;const days=ui.analyticsDate==='7d'?7:30;const cutoff=new Date(today+'T00:00:00');cutoff.setDate(cutoff.getDate()-days+1);const published=new Date(String(content.publishedAt||'')+'T00:00:00');return !Number.isNaN(published.getTime())&&published>=cutoff}
  function analyticsContentMatch(content){return content.status==='published'&&(ui.analyticsCategory==='all'||content.category===ui.analyticsCategory)&&analyticsDateMatch(content)}
  function csvCell(value){return '"'+String(value==null?'':value).replace(/"/g,'""')+'"'}
  function exportAnalytics(){const rows=store.contents.filter(analyticsContentMatch);const header=['标题','内容类型','发布时间','曝光量','点赞','收藏','评论','互动率'];const lines=[header].concat(rows.map(function(c){return [c.title,c.category,c.publishedAt,c.views,c.likes,c.saves,c.comments,(c.rate||0)+'%']})).map(function(row){return row.map(csvCell).join(',')});const blob=new Blob(['\ufeff'+lines.join('\r\n')],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download='ai-growth-analytics-'+today+'.csv';document.body.appendChild(link);link.click();link.remove();setTimeout(function(){URL.revokeObjectURL(url)},0);toast('分析数据已导出','已按当前筛选条件生成 CSV')}
