  function applyRange(range){const profiles=rangeProfiles();store.metrics.range=profiles[range]?range:'7d';store.metrics.cards=clone(profiles[store.metrics.range]);store.ai.context=currentContext();save();hydrateAnalyticsData().then(function(){render()})}
  function actionLabel(type){return type==='CREATE_TASK'?'创建任务':type==='CREATE_CONTENT'?'创建内容':'执行操作'}
  function createTask(payload){const title=String(payload&&payload.title||'').trim();if(!title){toast('任务标题不能为空');return null}const exists=store.tasks.some(t=>String(t.title||'').trim().toLowerCase()===title.toLowerCase()&&t.status!=='done');if(exists){toast('任务已存在','当前任务中心已有相同的未完成任务');return null}const task={id:uid('task'),title:title,priority:payload.priority||'medium',status:'todo',dueAt:payload.dueAt||today,source:payload.source||'ai',notes:payload.notes||'',contentId:payload.contentId||null,subtasks:Array.isArray(payload.subtasks)?payload.subtasks:[],history:[],result:''};store.tasks.unshift(task);save();toast('AI Action 已执行','任务已加入任务中心');return task}
  function executeAction(action){if(!action)return;if(action.type==='CREATE_TASK')return createTask(action.payload);if(action.type==='CREATE_CONTENT'){store.contents.unshift({id:'content_'+Date.now(),title:action.payload.title,category:action.payload.category||'运营经验',publishedAt:today,status:'draft',views:0,likes:0,saves:0,comments:0,rate:0});save();toast('AI Action 已执行','内容草稿已创建');render()}}
  function currentContext(){const ranked=store.contents.filter(function(c){return typeof analyticsContentMatch==='function'?analyticsContentMatch(c):c.status==='published'}).slice().sort(function(a,b){return rankValue(b,ui.rankMetric)-rankValue(a,ui.rankMetric)}).slice(0,5);return {page:ui.page,range:store.metrics.range,metrics:store.metrics.cards,trend:store.metrics.trend[ui.metric]||[],metric:ui.metric,rankMetric:ui.rankMetric,analyticsCategory:ui.analyticsCategory,analyticsDate:ui.analyticsDate,ranking:ranked.map(function(c){return {title:c.title,category:c.category,views:c.views,likes:c.likes,saves:c.saves,comments:c.comments,rate:c.rate}}),selectedContent:store.contents.filter(c=>c.status==='published').slice(0,3).map(c=>c.title)}}
  function parseAIJson(raw){const text=String(raw||'').trim().replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,'');try{return JSON.parse(text)}catch(e){return null}}
  function shouldSuggestTask(question){const lower=String(question||'').toLowerCase();return ['创建任务','安排','执行','做什么','怎么办','下一步','计划','发布','优化','开始做','帮我做'].some(function(word){return lower.includes(word)})}
  function aiTaskAction(question){const lower=String(question||'').toLowerCase();return {type:'CREATE_TASK',payload:{title:lower.includes('内容')||lower.includes('选题')?'执行下一轮内容选题计划':lower.includes('评论')||lower.includes('互动')?'优化内容结尾并回复高价值评论':'复盘当前数据并执行增长建议',priority:lower.includes('下降')||lower.includes('流量')?'high':'medium',dueAt:today,source:'ai',notes:'由 AI 运营总监基于当前页面数据生成。'}}}
  function normalizeAIAction(action,question){if(!shouldSuggestTask(question))return null;if(action&&action.type==='CREATE_TASK'&&action.payload&&String(action.payload.title||'').trim()){const p=action.payload;return {type:'CREATE_TASK',payload:{title:String(p.title).trim().slice(0,80),priority:['high','medium','low'].includes(p.priority)?p.priority:'medium',dueAt:p.dueAt||today,source:'ai',notes:String(p.notes||'由 AI 运营总监生成')}}}return aiTaskAction(question)}
function aiDirectorPrompt(){return '你是一位有 15 年实战经验的小红书 AI 运营总监。你做过账号定位、内容策略、爆款复盘、评论运营和增长实验，像一位真正的资深顾问一样与用户沟通。先理解用户在问什么，直接回答，不要每次都套用固定模板；如果信息不足，可以自然地追问一个最关键的问题。结合当前页面和账号数据给出有判断的建议，解释为什么，不要编造不存在的数据，也不要假装已经执行了动作。只有用户明确要求下一步、执行、安排、发布、优化或创建任务时，才返回 CREATE_TASK，否则 action 必须为 null。只返回严格 JSON，不要 Markdown，不要额外说明。格式：{"reply":"自然、具体、像真人顾问的中文回答，可使用分段和追问","action":null 或 {"type":"CREATE_TASK","payload":{"title":"任务标题","priority":"high|medium|low","dueAt":"'+today+'","source":"ai","notes":"任务执行说明"}}}。当前上下文：'+JSON.stringify(currentContext())}
function aiReply(q){const base='我看了下当前'+rangeLabel()+'的数据：曝光量 '+store.metrics.cards.exposure.toLocaleString()+'，互动率 '+store.metrics.cards.interaction+'%。';const lower=String(q||'').toLowerCase();if(lower.includes('流量')||lower.includes('下降'))return {text:'我先说结论：现在更像是互动承接出了问题，不是曝光完全没有了。教程型内容还能带来收藏，但结尾缺少让人愿意回答的问题，发布后的评论回复也不够及时。你可以先挑一篇最近的内容，把结尾改成一个具体问题；如果你希望，我再帮你把这一步拆成任务。',action:shouldSuggestTask(q)?store.insights[1].action:null};if(lower.includes('选题')||lower.includes('内容'))return {text:base+' 教程型内容目前最值得继续做，因为它给用户明确的方法，收藏表现也更稳定。你可以把它发展成连续主题，而不是每次换一个完全不同的方向。要不要我根据你的目标，再帮你收敛成 3 个具体选题？',action:shouldSuggestTask(q)?aiTaskAction(q):null};return {text:base+' 教程型内容是目前比较稳定的增长来源。你可以继续问我某个指标、某篇内容，或者告诉我你现在最想解决的运营问题，我会和你一起拆开看。',action:shouldSuggestTask(q)?store.insights[0].action:null}}
  async function aiAsk(question){question=String(question||'').trim();if(!question)return;ui.lastAIQuestion=question;ui.aiStatus='loading';const context=currentContext();store.ai.messages.push({role:'user',text:question});store.ai.context=context;save();render();let reply;try{const raw=await aiRequest('',store.ai.messages.slice(-10),aiDirectorPrompt());const parsed=parseAIJson(raw);reply={text:parsed&&(parsed.reply||parsed.text)?(parsed.reply||parsed.text):raw,action:normalizeAIAction(parsed&&parsed.action,question)};ui.aiStatus='idle'}catch(error){const fallback=aiReply(question);reply=fallback;const code=error&&error.code;ui.aiStatus=code==='AI_CONFIG_MISSING'?'config':code==='AI_TIMEOUT'?'timeout':code==='AI_NETWORK_ERROR'?'offline':'model';if(code==='AI_CONFIG_MISSING')toast('AI 总监未连接','请先在设置中配置服务端 Key');else if(code==='AI_TIMEOUT')toast('AI 请求超时','可以稍后重试');else if(code==='AI_NETWORK_ERROR')toast('网络异常','请检查网络连接');else toast('模型服务异常','已保留当前对话，可以稍后重试')}store.ai.messages.push({role:'assistant',text:reply.text,action:reply.action,sources:[''+rangeLabel()+'：曝光量 '+store.metrics.cards.exposure.toLocaleString(),'互动率 '+store.metrics.cards.interaction+'%','当前页面 '+ui.page]});store.ai.history.push({question,context:context,at:new Date().toISOString()});store.ai.context=currentContext();save();render()}
