function connectionInfo(){
  const defaults={status:'unbound',provider:'xiaohongshu',accountId:'',endpoint:'',credentialConfigured:false,lastVerifiedAt:null,lastSyncedAt:null,lastError:'',permissions:[]};
  if(!store.account.connection)store.account.connection={};
  Object.keys(defaults).forEach(function(key){if(store.account.connection[key]===undefined)store.account.connection[key]=defaults[key]});
  if(store.account.status==='connected'||store.account.status==='active'){store.account.connection.status='connected';store.account.connection.accountId=store.account.accountId||store.account.connection.accountId;store.account.connection.permissions=Array.isArray(store.account.permissions)?store.account.permissions:store.account.connection.permissions;}
  if(!ui.accountCredential&&store.account.connection.status==='connected'&&store.account.connection.credentialConfigured){store.account.connection.status='configured';store.account.connected=false;store.account.status='configured'}
  return store.account.connection;
}
function connectionLabel(status){return {unbound:'未接入',configured:'已配置，待验证',syncing:'同步中',connected:'已连接',error:'连接失败'}[status]||'未接入'}
function connectionBadge(status){return status==='connected'?'done':status==='error'?'high':status==='syncing'?'medium':'gray'}

 function aiConfig(){const d={provider:'deepseek',endpoint:'',model:'deepseek-chat',status:'unconfigured',hasKey:false,lastError:''};if(!store.ai.providerConfig)store.ai.providerConfig={};Object.keys(d).forEach(function(key){if(store.ai.providerConfig[key]===undefined)store.ai.providerConfig[key]=d[key]});if(!store.ai.providerConfig.model)store.ai.providerConfig.model=d.model;if(store.ai.providerConfig.status==='connected')store.ai.providerConfig.status='configured';return store.ai.providerConfig}
function aiConfigLabel(s){return {unconfigured:'未配置',configured:'已配置，待测试',syncing:'测试中',connected:'已连接',error:'连接失败'}[s]||'未配置'}
function aiConfigClass(s){return s==='connected'?'done':s==='error'?'high':s==='syncing'?'medium':'gray'}
function aiUrl(){const c=aiConfig(),u=(c.endpoint||'').replace(/\/$/,'');return u.endsWith('/chat/completions')?u:u+'/chat/completions'}
async function aiRequest(prompt,history,systemPrompt){
  const messages=[{role:'system',content:systemPrompt||'你是小红书内容运营顾问，请用中文简洁回答。'}];
  (history||[]).slice(-10).forEach(function(m){if(m&&m.text)messages.push({role:m.role==='assistant'?'assistant':'user',content:m.text})});
  if(prompt)messages.push({role:'user',content:prompt});
  const controller=new AbortController();const timer=setTimeout(function(){controller.abort()},20000);
  try{const r=await fetch('/api/ai',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({messages:messages,provider:ui.aiProvider}),signal:controller.signal});const j=await r.json().catch(function(){return {}});if(!r.ok){const detail=j.error&&typeof j.error==='object'?j.error:{};const error=Error(detail.message||j.error||('服务返回 '+r.status));error.code=detail.code||j.code||'AI_MODEL_ERROR';error.status=r.status;throw error}const m=j.choices&&j.choices[0]&&j.choices[0].message&&j.choices[0].message.content;if(!m){const error=Error('响应缺少 choices[0].message.content');error.code='AI_RESPONSE_INVALID';throw error}return m}catch(error){if(error&&error.name==='AbortError'){const timeout=Error('AI 请求超过 20 秒未响应');timeout.code='AI_TIMEOUT';throw timeout}if(typeof navigator!=='undefined'&&navigator.onLine===false){error.code='AI_NETWORK_ERROR'}throw error}finally{clearTimeout(timer)}}
function settingsAI(){const c=aiConfig();const statusState=c.status==='syncing'?stateCard('loading','正在测试 AI 服务','正在验证服务端模型连接，请稍候。'):'';return '<div class="growth-card" id="ai-settings-panel" style="margin-top:16px"><div class="growth-card-head"><div><strong>AI 服务配置</strong><div class="growth-note">多个 AI 供应商密钥和模型由服务端环境变量管理</div></div><span class="growth-badge '+aiConfigClass(c.status)+'">'+aiConfigLabel(c.status)+'</span></div><div class="growth-connection-meta"><div><small>服务商</small><b>DeepSeek</b></div><div><small>模型</small><b>由 DEEPSEEK_MODEL 提供</b></div><div><small>密钥</small><b>仅服务端读取</b></div><div><small>配置文件</small><b>.env（不提交 Git）</b></div></div>'+statusState+'<p class="growth-note">浏览器不会收集、保存或提交 API Key。请在本地服务端的 .env 文件中配置一个或多个供应商，然后在下方选择当前供应商。</p>'+(c.lastError?stateCard(c.lastError.indexOf('DEEPSEEK_API_KEY')>=0?'config':'model',c.lastError.indexOf('DEEPSEEK_API_KEY')>=0?'API Key 未配置':'模型服务异常',c.lastError,'test-ai','重新测试'):'')+'<div class="growth-drawer-actions"><button class="growth-btn primary" data-action="test-ai-config">测试服务端连接</button></div></div>'}
