async function generateWithAI(){if(ui.creationStatus==='generating')return;const topic=(document.getElementById('create-topic')&&document.getElementById('create-topic').value||'').trim(),type=document.getElementById('create-type')&&document.getElementById('create-type').value||'教程型内容',goal=document.getElementById('create-goal')&&document.getElementById('create-goal').value||'提升收藏',tone=document.getElementById('create-tone')&&document.getElementById('create-tone').value||'清晰专业',material=(document.getElementById('create-material')&&document.getElementById('create-material').value||'').trim();if(!topic&&!material){toast('请输入主题或素材','内容不能为空，暂未发送请求');const field=document.getElementById('create-topic');if(field)field.focus();return}ui.creationBrief={goal:goal,type:type,tone:tone,topic:topic,material:material};ui.creationStatus='generating';render();const prompt='请为主题《'+(topic||'根据素材提炼主题')+'》生成小红书完整方案。目标：'+goal+'；内容类型：'+type+'；语气：'+tone+'；素材：'+(material||'暂无')+'。返回 JSON，正文要可直接发布。';try{const result=await apiFetch('/api/ai/generate',{method:'POST',body:JSON.stringify({content:prompt,platform:'xiaohongshu',provider:ui.aiProvider})});const raw=String(result.content||'').trim();if(!raw)throw Object.assign(new Error('服务端返回为空'),{code:'AI_RESPONSE_INVALID'});const parsed=parseAIJson(raw)||{};const titles=Array.isArray(parsed.titles)&&parsed.titles.length?parsed.titles.map(String).slice(0,5):[String(parsed.title||topic||'服务端生成内容')];const plan={positioning:parsed.positioning||'服务端 AI 已生成内容定位。',angle:parsed.angle||'服务端 AI 已生成选题角度。',audience:parsed.audience||'服务端 AI 已生成目标受众。',hook:parsed.hook||'',structure:parsed.structure||'',visualPlan:parsed.visualPlan||[],hashtags:parsed.hashtags||[],cta:parsed.cta||'',publishAdvice:parsed.publishAdvice||''};ui.creationDraft={selectedTitle:titles[0],title:String(parsed.title||titles[0]),summary:String(parsed.summary||'服务端 AI 已返回完整方案。'),titles:titles,body:String(parsed.body||raw),structure:plan.structure,plan:plan};ui.creationStatus='idle';saveCreationVersion('服务端 AI 方案');persistCreation();save();render();toast('AI 方案已生成','结果来自服务端 API')}catch(error){ui.creationStatus=error.code==='AUTH_REQUIRED'?'auth':error.code==='AI_CONFIG_MISSING'?'config':error.code==='AI_TIMEOUT'?'timeout':error.code==='AI_NETWORK_ERROR'?'offline':'model';render();if(error.code==='AUTH_REQUIRED')toast('请先登录','登录后才能调用服务端 AI');else if(error.code==='AI_CONFIG_MISSING')toast('服务端未配置 AI','请在设置中配置当前供应商');else toast('AI 生成失败',error.message||'请稍后重试')}}
function settingsPro(){const c=connectionInfo();const verified=c.lastVerifiedAt?new Date(c.lastVerifiedAt).toLocaleString('zh-CN'):'尚未验证';const synced=c.lastSyncedAt?new Date(c.lastSyncedAt).toLocaleString('zh-CN'):'尚未同步';const state=c.status==='unbound'?stateCard('account','账号未绑定','绑定小红书账号后，真实指标、内容和权限才会同步到工作台。','connect-account','配置账号接入'):c.status==='connected'&&(!Array.isArray(c.permissions)||!c.permissions.length)?stateCard('permission','暂无数据权限','账号已连接，但服务端没有返回可用数据权限。','connect-account','检查授权'):'';return '<div class="growth-page-head"><div><h1>设置</h1><p>管理数据源、AI 接入和运营偏好。用户资料、套餐和账户操作请前往用户中心。</p></div><span class="growth-badge '+connectionBadge(c.status)+'">'+connectionLabel(c.status)+'</span></div>'+state+'<div class="growth-grid"><div class="growth-card"><div class="growth-card-head"><strong>数据源接入</strong><span class="growth-badge '+connectionBadge(c.status)+'">'+connectionLabel(c.status)+'</span></div>'+(c.status==='syncing'?stateCard('loading','正在同步账号数据','正在向后端授权服务请求最新指标和内容。'):c.status==='error'?'': '')+'<p class="growth-note">真实数据通过你配置的后端授权服务读取。访问令牌只应由后端保存，浏览器只记录连接状态。</p><div class="growth-connection-meta"><div><small>服务商</small><b>小红书</b></div><div><small>账号 ID</small><b>'+esc(c.accountId||'未配置')+'</b></div><div><small>最近验证</small><b>'+esc(verified)+'</b></div><div><small>最近同步</small><b>'+esc(synced)+'</b></div></div>'+(c.lastError?stateCard('model','账号服务异常',c.lastError,'test-account','重新测试'):'')+'<div class="growth-drawer-actions"><button class="growth-btn" data-action="connect-account">'+(c.status==='unbound'?'配置接入':'修改配置')+'</button><button class="growth-btn" data-action="oauth-start">小红书授权（内测）</button><button class="growth-btn" data-action="test-account" '+(c.status==='unbound'?'disabled':'')+'>测试连接</button></div><div class="growth-drawer-actions"><button class="growth-btn" data-action="sync-account" '+(c.status==='connected'?'':'disabled')+'>立即同步</button><button class="growth-btn" data-action="disconnect-account" '+(c.status==='unbound'?'disabled':'')+'>断开账号</button></div></div><div class="growth-card"><div class="growth-card-head"><strong>AI 接入偏好</strong><span class="growth-note">当前页面内存</span></div><p class="growth-note">AI 模型、API 地址和密钥配置只属于设置项。用户资料与小红书账号信息请在用户中心维护。</p><button class="growth-btn" data-page="settings">AI 配置在本页下方</button></div></div><div class="growth-card" style="margin-top:16px"><div class="growth-card-head"><strong>同步范围与权限</strong><span class="growth-note">由授权服务返回</span></div><div class="growth-permissions">'+(c.permissions.length?c.permissions.map(function(x){return '<span class="growth-permission">✓ '+esc(x)+'</span>'}).join(''):'<span class="growth-note">验证连接后显示可用权限。</span>')+'</div></div>'}function openConnectionForm(){const c=connectionInfo();const body='<div class="growth-form-row">'+formSelect('provider','平台',[['xiaohongshu','小红书']],'xiaohongshu')+formField('accountId','账号 ID',c.accountId||store.account.id)+'</div>'+formField('endpoint','后端授权服务地址',c.endpoint||'','url')+'<label class="growth-form-label">访问令牌（仅用于本次验证）<input name="accessToken" type="password" autocomplete="off" placeholder="不写入浏览器"></label><p class="growth-note">需要一个提供 /health 和 /sync 接口的后端适配器。前端不会保存令牌。</p>';modal('配置账号接入','保存后先进入“待验证”，只有测试接口成功才会显示已连接。',body,'保存配置',function(v){if(!v.accountId.trim()||!v.endpoint.trim()){toast('请填写账号 ID 和后端服务地址');return false}const info=connectionInfo();info.provider=v.provider;info.accountId=v.accountId.trim();info.endpoint=v.endpoint.trim().replace(/\/$/,'');info.credentialConfigured=Boolean(v.accessToken);ui.accountCredential=v.accessToken||'';info.status='configured';info.lastError='';store.account.id=info.accountId;store.account.connected=false;store.account.status='configured';save();render();toast('接入配置已保存','请点击测试连接')})}
async function testAccountConnection(){const c=connectionInfo();if(!c.endpoint){toast('请先配置后端服务地址');return}c.status='syncing';c.lastError='';save();render();try{const response=await fetch('/api/account',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'health',endpoint:c.endpoint,accountId:c.accountId,accessToken:ui.accountCredential})});const payload=await response.json().catch(function(){return {}});if(!response.ok)throw new Error(payload.error||('服务返回 '+response.status));if(payload.accountId&&String(payload.accountId)!==String(c.accountId))throw new Error('服务返回的账号 ID 与配置不一致');c.status='connected';c.lastVerifiedAt=new Date().toISOString();c.permissions=Array.isArray(payload.permissions)?payload.permissions:['read_metrics','read_contents','read_comments'];store.account.connected=true;store.account.status='active';save();render();toast('账号连接成功','身份和权限已验证')}catch(error){c.status='error';c.lastError='无法连接后端授权服务：'+error.message;c.lastVerifiedAt=null;store.account.connected=false;save();render();toast('连接测试失败','请检查服务地址、凭据和账号 ID')}}
async function syncAccountData(){const c=connectionInfo();if(ui.serverReady){c.status='syncing';c.lastError='';save();render();try{const result=await apiFetch('/api/account/sync',{method:'POST'});if(result.account)store.account=Object.assign(store.account,result.account);if(Array.isArray(result.contents))store.contents=result.contents;if(result.cards){store.metrics.cards=Object.assign(store.metrics.cards,{followers:result.cards.followers,exposure:result.cards.exposure,likes:result.cards.likes,saves:result.cards.saves,comments:result.cards.comments,interaction:result.cards.interaction});}c.status='connected';c.lastSyncedAt=result.updatedAt||new Date().toISOString();c.lastError='';store.meta=Object.assign({},store.meta,{source:'server',lastSyncAt:c.lastSyncedAt});save();render();toast('数据同步完成','账号数据已回流到分析页')}catch(error){c.status=error.code==='ACCOUNT_NOT_CONNECTED'?'configured':'error';c.lastError=error.message||'同步失败';save();render();toast('数据同步失败',error.message||'请先完成账号授权')}return}if(c.status!=='connected'){toast('请先通过连接测试');return}c.status='syncing';save();render();try{const response=await fetch('/api/account',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'sync',endpoint:c.endpoint,accountId:c.accountId,accessToken:ui.accountCredential})});const payload=await response.json().catch(function(){return {}});if(!response.ok)throw new Error(payload.error||('服务返回 '+response.status));if(payload.metrics)store.metrics.cards=Object.assign(store.metrics.cards,payload.metrics);if(payload.trend)store.metrics.trend=Object.assign(store.metrics.trend,payload.trend);if(Array.isArray(payload.contents))store.contents=payload.contents;c.status='connected';c.lastSyncedAt=new Date().toISOString();c.lastError='';save();render();toast('数据同步完成','指标、趋势和内容已更新')}catch(error){c.status='error';c.lastError='同步失败：'+error.message;save();render();toast('数据同步失败','已保留上次成功数据')}}
 async function schedulePublish(contentId, plannedAt, mode){const content=store.contents.find(function(item){return item.id===contentId});if(!content)return;if(ui.serverReady){try{const result=await apiFetch('/api/content/publish',{method:'POST',body:JSON.stringify({contentId:contentId,plannedAt:plannedAt||today,mode:mode||'schedule'})});if(result.content)Object.assign(content,result.content);if(result.job)content.publishJobId=result.job.id;save();render();toast('发布计划已保存','服务端已记录计划时间')}catch(error){toast('发布计划失败',error.message||'请稍后重试')}return}content.status='scheduled';content.plannedAt=plannedAt||today;content.dataSource='local-demo';save();render();toast('已保存本地发布计划','登录并绑定账号后可同步到服务端')}
 async function retryPublish(contentId){const content=store.contents.find(function(item){return item.id===contentId});if(!content)return;if(ui.serverReady&&content.publishJobId){try{const result=await apiFetch('/api/content/publish/retry',{method:'POST',body:JSON.stringify({jobId:content.publishJobId})});if(result.job){content.status='scheduled';content.publishError='';content.plannedAt=content.plannedAt||today}save();render();toast('已重新加入发布队列','等待账号服务处理')}catch(error){toast('重试发布失败',error.message||'请稍后重试')}return}content.status='scheduled';content.publishError='';save();render();toast('已重新安排发布','当前为本地演示状态')}
 function disconnectAccount(){const c=connectionInfo();c.status='unbound';c.accountId='';c.endpoint='';c.credentialConfigured=false;c.lastVerifiedAt=null;c.lastSyncedAt=null;c.lastError='';c.permissions=[];store.account.connected=false;store.account.status='demo';save();render();toast('账号已断开','当前回到本地数据模式')}

