function aiPanel(){const busy=ui.aiStatus==='loading';let status='';if(ui.aiStatus==='loading')status=stateCard('loading','AI 正在思考','正在结合当前页面数据组织回答，请稍候。');else if(ui.aiStatus==='config')status=stateCard('config','API Key 未配置','服务端尚未配置 DeepSeek API Key，当前回答使用本地兜底。','go-settings','去设置配置');else if(ui.aiStatus==='timeout')status=stateCard('timeout','请求超时','模型服务超过 20 秒未响应，当前回答未丢失。','retry-ai','重新请求');else if(ui.aiStatus==='offline')status=stateCard('offline','网络断开','暂时无法访问 AI 服务，请恢复网络后重试。','retry-ai','重新请求');else if(ui.aiStatus==='model')status=stateCard('model','模型服务异常','模型服务暂时不可用，当前回答使用本地兜底。','retry-ai','重新请求');return '<aside class="growth-ai"><div class="growth-ai-head"><span class="growth-avatar">✦</span><div><b>AI 运营总监</b><small>15 年实战经验 · 当前上下文：'+rangeLabel()+' · '+ui.page+'</small></div><button style="margin-left:auto;border:0;background:transparent" data-action="toggle-ai">×</button></div><div class="growth-ai-body" id="ai-body"><div class="growth-ai-message"><span class="growth-avatar">✦</span><div class="growth-ai-bubble">你好，我会像你的运营顾问一样和你一起看数据、聊内容。你可以直接告诉我遇到的问题，不需要用固定格式提问。</div></div>'+store.ai.messages.map(messageHtml).join('')+status+'</div><div class="growth-ai-composer"><textarea id="ai-input" placeholder="'+(busy?'AI 正在思考…':'直接说说你现在遇到的问题…')+'" '+(busy?'disabled':'')+'></textarea><button data-action="send-ai" '+(busy?'disabled':'')+'>发送</button></div></aside>'}
function reviewAction(action){if(!action||action.type!=='CREATE_TASK'||!action.payload)return;const p=action.payload;const body=formField('title','任务标题',p.title||'')+'<div class="growth-form-row">'+formSelect('priority','优先级',[['high','高'],['medium','中'],['low','低']],p.priority||'medium')+formField('dueAt','截止日期',p.dueAt||today,'date')+'</div>'+formText('notes','执行说明',p.notes||'');modal('确认创建任务','AI 已提出一个执行建议，请确认或修改后再加入任务中心。',body,'确认创建',function(v){if(!v.title.trim())return false;executeAction({type:'CREATE_TASK',payload:{title:v.title.trim(),priority:v.priority,dueAt:v.dueAt||today,source:'ai',notes:v.notes||''}});return true})}   function messageHtml(m){const copy=esc(m.text).replace(/\n/g,'<br>');const sourceHtml=m.sources&&m.sources.length?'<div class="growth-ai-sources">数据依据：'+m.sources.map(function(x){return esc(x)}).join(' · ')+'</div>':'';const actionHtml=m.action?'<div class="growth-ai-flow"><b>AI Action</b><span>'+m.action.type+'</span></div><div class="growth-ai-action"><b>'+esc(m.action.payload.title)+'</b><button data-review-action="'+esc(JSON.stringify(m.action))+'">查看并创建任务</button></div>':'';if(m.role==='user')return '<div class="growth-ai-message user"><div class="growth-ai-bubble">'+copy+'</div></div>';return '<div class="growth-ai-message"><span class="growth-avatar">✦</span><div class="growth-ai-bubble">'+copy+sourceHtml+actionHtml+'</div></div>'}
